SIZES = ["small", "medium", "large"]


class ParkingLot:
    def __init__(self, small: int, medium: int, large: int) -> None:
        # Free spots of each size, by its index in SIZES.
        self.free_spots = [small, medium, large]
        # Each parked car's spot size, as an index in SIZES.
        self.parked: dict[str, int] = {}

    def park(self, car: str, size: str) -> str:
        for i in range(SIZES.index(size), len(SIZES)):
            if self.free_spots[i] > 0:
                self.free_spots[i] -= 1
                self.parked[car] = i
                return SIZES[i]
        return "full"

    def leave(self, car: str) -> bool:
        if car not in self.parked:
            return False
        self.free_spots[self.parked.pop(car)] += 1
        return True

    def free(self, size: str) -> int:
        return self.free_spots[SIZES.index(size)]


small, medium, large = map(int, input().split())
lot = ParkingLot(small, medium, large)
q = int(input())
for _ in range(q):
    op, *args = input().split()
    if op == "park":
        print(lot.park(args[0], args[1]))
    elif op == "leave":
        print("true" if lot.leave(args[0]) else "false")
