#include <string>

const std::array<std::string, 3> kSizes = {"small", "medium", "large"};
const std::map<std::string, int> kSizeIndex = {{"small", 0}, {"medium", 1}, {"large", 2}};

class ParkingLot {
public:
    ParkingLot(int small, int medium, int large) : freeSpots_{small, medium, large} {}

    std::string park(const std::string& car, const std::string& size) {
        for (int i = kSizeIndex.at(size); i < 3; i++) {
            if (freeSpots_[i] > 0) {
                freeSpots_[i]--;
                parked_[car] = i;
                return kSizes[i];
            }
        }
        return "full";
    }

    bool leave(const std::string& car) {
        auto it = parked_.find(car);
        if (it == parked_.end()) {
            return false;
        }
        freeSpots_[it->second]++;
        parked_.erase(it);
        return true;
    }

    int free(const std::string& size) const { return freeSpots_[kSizeIndex.at(size)]; }

private:
    std::array<int, 3> freeSpots_;      // free spots of each size, by index in kSizes
    std::map<std::string, int> parked_; // each parked car's spot size, as an index
};

int main() {
    int small, medium, large, q;
    std::cin >> small >> medium >> large >> q;
    ParkingLot lot(small, medium, large);
    for (int i = 0; i < q; i++) {
        std::string op, a, b;
        std::cin >> op >> a;
        if (op == "park") {
            std::cin >> b;
            std::cout << lot.park(a, b) << "\n";
        } else if (op == "leave") {
            std::cout << (lot.leave(a) ? "true" : "false") << "\n";
