class ParkingLot {
    private static final List<String> SIZES = List.of("small", "medium", "large");
    private final int[] freeSpots; // free spots of each size, by index in SIZES
    private final Map<String, Integer> parked = new HashMap<>(); // each car's spot size index

    ParkingLot(int small, int medium, int large) {
        freeSpots = new int[] {small, medium, large};
    }

    String park(String car, String size) {
        for (int i = SIZES.indexOf(size); i < SIZES.size(); i++) {
            if (freeSpots[i] > 0) {
                freeSpots[i]--;
                parked.put(car, i);
                return SIZES.get(i);
            }
        }
        return "full";
    }

    boolean leave(String car) {
        Integer spot = parked.remove(car);
        if (spot == null) {
            return false;
        }
        freeSpots[spot]++;
        return true;
    }

    int free(String size) {
        return freeSpots[SIZES.indexOf(size)];
    }
}

