package main

import "fmt"

var sizes = []string{"small", "medium", "large"}
var sizeIndex = map[string]int{"small": 0, "medium": 1, "large": 2}

// ParkingLot has spots in three sizes and remembers where each car is.
type ParkingLot struct {
	freeSpots []int          // free spots of each size, by index in sizes
	parked    map[string]int // each parked car's spot size, as an index
}

func newParkingLot(small, medium, large int) *ParkingLot {
	return &ParkingLot{freeSpots: []int{small, medium, large}, parked: map[string]int{}}
}

func (p *ParkingLot) park(car, size string) string {
	for i := sizeIndex[size]; i < len(sizes); i++ {
		if p.freeSpots[i] > 0 {
			p.freeSpots[i]--
			p.parked[car] = i
			return sizes[i]
		}
	}
	return "full"
}

func (p *ParkingLot) leave(car string) bool {
	spot, ok := p.parked[car]
	if ok {
		p.freeSpots[spot]++
		delete(p.parked, car)
	}
	return ok
}

func (p *ParkingLot) free(size string) int {
	return p.freeSpots[sizeIndex[size]]
}

func main() {
	var small, medium, large, q int
	fmt.Scan(&small, &medium, &large, &q)
	lot := newParkingLot(small, medium, large)
	for i := 0; i < q; i++ {
		var op, a, b string
		fmt.Scan(&op, &a)
		switch op {
		case "park":
			fmt.Scan(&b)
			fmt.Println(lot.park(a, b))
		case "leave":
			fmt.Println(lot.leave(a))
		case "free":
			fmt.Println(lot.free(a))
		}
	}
}

